create or replace function public._co_ok(_org uuid) returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from organizations o join user_active_context c on c.org_id=o.id where o.id=_org and o.is_active and c.user_id=auth.uid() and ((is_platform_admin() and c.role='org_owner' and c.school_id is not null and exists(select 1 from schools s where s.id=c.school_id and s.org_id=_org and s.is_active)) or exists(select 1 from memberships m where m.user_id=auth.uid() and m.org_id=_org and m.is_active and not m.branch_suspended and m.role in ('org_owner','principal','vice_principal','supervisor','teacher') and c.role=m.role::text and c.school_id is not distinct from m.school_id and (m.school_id is null or exists(select 1 from schools s where s.id=m.school_id and s.org_id=_org and s.is_active))))) $$;
create or replace function private.co_community(_org uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare c conversations; u uuid; begin if not _co_ok(_org) then raise exception 'غير مصرح'; end if; perform pg_advisory_xact_lock(hashtext('co:'||_org)); select * into c from conversations where dedupe_key='co:'||_org; if c.id is null then insert into conversations(org_id,kind,group_type,title,membership_mode,history_policy,dedupe_key) values(_org,'group','custom','المجتمع المهني','derived','full','co:'||_org) returning * into c; end if; for u in select distinct m.user_id from memberships m join organizations o on o.id=m.org_id where m.org_id=_org and m.is_active and not m.branch_suspended and o.is_active and m.role in ('org_owner','principal','vice_principal','supervisor','teacher') and (m.school_id is null or exists(select 1 from schools s where s.id=m.school_id and s.is_active and s.org_id=_org)) loop perform _add_member(c.id,u,'member','derived',c.created_at); end loop; perform _add_member(c.id,auth.uid(),'member','derived',c.created_at); return to_jsonb(c); end $$;
revoke all on function private.co_community(uuid) from public,anon; grant execute on function private.co_community(uuid) to authenticated,service_role;
do $$ declare d text; begin d:=pg_get_functiondef('public.perm_catalog()'::regprocedure); d:=replace(d,'FUNCTION public.perm_catalog()','FUNCTION private.co_catalog_base()'); execute d; end $$;
revoke all on function private.co_catalog_base() from public,anon,authenticated; grant execute on function private.co_catalog_base() to service_role;
create or replace function public.perm_catalog() returns jsonb language sql stable security definer set search_path=public as $$ with b as (select private.co_catalog_base() c offset 0) select jsonb_set(jsonb_set(c,'{areas}',(select coalesce(jsonb_agg(a),'[]'::jsonb) from jsonb_array_elements(c->'areas') a where a->>'key'<>'collaboration')||'[{"key":"collaboration","label":"التعاون"}]'::jsonb),'{sections}',(select coalesce(jsonb_agg(s),'[]'::jsonb) from jsonb_array_elements(c->'sections') s where s->>'key' not in ('co_community_info','co_library_info'))||'[{"key":"co_community_info","label":"المجتمع المهني","parent":"collaboration","actions":[],"scopes":[],"locked_reason":"متاح لمالك المجموعة ومالك المنصة داخل المجموعة المختارة، وللأدوار المهنية المعتمدة فقط","children":["الرسائل النصية والصوتية والملفات","اسم المرسل ودوره وفرعه والتوقيت"]},{"key":"co_library_info","label":"المكتبة الرقمية","parent":"collaboration","actions":[],"scopes":[],"locked_reason":"الوصول وفق الدور والمؤسسة؛ أصحاب المحتوى يديرونه والمالك يشرف على الحذف","children":["أنشطة","مواد تعليمية","أوراق عمل","مذكرات","ملخصات","دورات","معاينة وتنزيل وطباعة وتفاعلات"]}]'::jsonb) from b $$;